"""Relational division, bags, coverage, similarity and small bounded searches."""
from _draft_helpers import topic

S = """
CREATE TABLE person(id INTEGER PRIMARY KEY,name TEXT);
INSERT INTO person VALUES(1,'Ann'),(2,'Bob'),(3,'Cara'),(4,'Dan');
CREATE TABLE skill(person_id INTEGER,skill TEXT,PRIMARY KEY(person_id,skill));
INSERT INTO skill VALUES(1,'SQL'),(1,'Python'),(2,'SQL'),(3,'SQL'),(3,'Python'),(3,'Lua'),(4,'Lua'),(4,'Rust');
CREATE TABLE requirement(skill TEXT PRIMARY KEY);
INSERT INTO requirement VALUES('SQL'),('Python');
CREATE TABLE bag(side TEXT,k TEXT);
INSERT INTO bag VALUES('L','A'),('L','A'),('L','B'),('L','C'),('R','A'),('R','B'),('R','B'),('R','D');
CREATE TABLE team_member(team TEXT,person_id INTEGER,PRIMARY KEY(team,person_id));
INSERT INTO team_member VALUES('T1',1),('T1',2),('T2',1),('T2',3),('T3',2),('T3',3),('T3',4);
"""
def T(n,slug,title,concepts,explain,q,out,p,a,b):
    return topic(n,slug,title,"relational",concepts,explain,S,q,out,p,a,b)

LESSONS = [
 T(292,"relational-division-all","关系除法查满足全部要求的人",["关系除法","双重 NOT EXISTS","全部条件"],
   "没有任何一条要求是此人缺少的，就是满足全部要求。双重 NOT EXISTS 表达这种全称逻辑，Ann 和 Cara 都具备 SQL、Python，因此合格；Cara 多出的 Lua 不影响结果。该写法不依赖固定要求数量。",
   "SELECT p.name FROM person p WHERE NOT EXISTS(SELECT 1 FROM requirement r WHERE NOT EXISTS(SELECT 1 FROM skill s WHERE s.person_id=p.id AND s.skill=r.skill)) ORDER BY p.name;","Ann\nCara",
   ["具备任意一个要求不能替代全部要求。","要求为空时该逻辑对所有人都成立。"],
   ("找出至少满足一条要求的人。","一层 EXISTS 查技能与要求连接。","SELECT p.name FROM person p WHERE EXISTS(SELECT 1 FROM skill s JOIN requirement r USING(skill) WHERE s.person_id=p.id) ORDER BY p.name;","Ann\nBob\nCara"),
   ("找出一条要求都不满足的人。","对交集使用 NOT EXISTS。","SELECT p.name FROM person p WHERE NOT EXISTS(SELECT 1 FROM skill s JOIN requirement r USING(skill) WHERE s.person_id=p.id) ORDER BY p.name;","Dan")),
 T(293,"relational-exact-set","技能集合恰好相等而非仅覆盖",["集合相等","双向包含","额外属性"],
   "集合相等需要既不缺少要求，也没有额外技能。Ann 恰有 SQL、Python，Cara 虽覆盖要求却多 Lua，所以只有 Ann。两个方向的反存在分别排除缺项与额外项，比比较技能总数更直接可靠。",
   "SELECT p.name FROM person p WHERE NOT EXISTS(SELECT skill FROM requirement EXCEPT SELECT skill FROM skill WHERE person_id=p.id) AND NOT EXISTS(SELECT skill FROM skill WHERE person_id=p.id EXCEPT SELECT skill FROM requirement) ORDER BY p.name;","Ann",
   ["数量相等不能证明集合相等。","EXCEPT 去重，若重复次数有意义需使用多重集合算法。"],
   ("列出覆盖要求但还有额外技能的人。","全覆盖且存在非要求技能。","SELECT p.name FROM person p WHERE NOT EXISTS(SELECT skill FROM requirement EXCEPT SELECT skill FROM skill WHERE person_id=p.id) AND EXISTS(SELECT skill FROM skill WHERE person_id=p.id EXCEPT SELECT skill FROM requirement) ORDER BY p.name;","Cara"),
   ("列出 Cara 的额外技能。","技能集合减要求集合。","SELECT skill FROM skill WHERE person_id=3 EXCEPT SELECT skill FROM requirement ORDER BY skill;","Lua")),
 T(294,"missing-requirement-grid","交叉要求网格返回每人的缺项",["CROSS JOIN","覆盖网格","缺项清单"],
   "person 与 requirement 的笛卡尔积代表每个人应具备的技能格，再反查实际 skill。Bob 缺 Python，Dan 缺 Python 和 SQL，完整清单比仅返回不合格者更可操作。要求很大时网格成本也会变大，应按当前范围过滤。",
   "SELECT p.name,r.skill FROM person p CROSS JOIN requirement r WHERE NOT EXISTS(SELECT 1 FROM skill s WHERE s.person_id=p.id AND s.skill=r.skill) ORDER BY p.name,r.skill;","Bob|Python\nDan|Python\nDan|SQL",
   ["维度交叉会扩展行数，必须有明确范围。","缺项查询不能用内连接，缺失本身没有匹配行。"],
   ("按人统计缺少要求数量，包括零。","相关子查询计数。","SELECT p.name,(SELECT count(*) FROM requirement r WHERE NOT EXISTS(SELECT 1 FROM skill s WHERE s.person_id=p.id AND s.skill=r.skill)) FROM person p ORDER BY p.name;","Ann|0\nBob|1\nCara|0\nDan|2"),
   ("计算完整要求网格应有格数。","人数乘要求数。","SELECT (SELECT count(*) FROM person)*(SELECT count(*) FROM requirement);","8")),
 T(295,"empty-requirements-vacuity","空要求集合中的全称逻辑",["空集合","真空真","关系逻辑"],
   "临时要求集合为空时，不存在任何缺少要求的人，双重反存在对四人都成立。这称为全称命题的真空真，不是 SQL 错误。若产品认为没有配置要求就不能通过，应额外要求规则集合非空。",
   "WITH req(skill) AS(SELECT skill FROM requirement WHERE 0) SELECT p.name FROM person p WHERE NOT EXISTS(SELECT 1 FROM req r WHERE NOT EXISTS(SELECT 1 FROM skill s WHERE s.person_id=p.id AND s.skill=r.skill)) ORDER BY p.name;","Ann\nBob\nCara\nDan",
   ["空规则默认通过是否合理属于业务决策。","用匹配数>0 改写会改变空集合语义。"],
   ("空要求下增加必须至少一条规则后返回人数。","额外 EXISTS(req) 会拒绝所有人。","WITH req(skill) AS(SELECT skill FROM requirement WHERE 0) SELECT count(*) FROM person p WHERE EXISTS(SELECT 1 FROM req) AND NOT EXISTS(SELECT 1 FROM req r WHERE NOT EXISTS(SELECT 1 FROM skill s WHERE s.person_id=p.id AND s.skill=r.skill));","0"),
   ("验证空集合上的 COUNT 与 SUM 不同。","COUNT 为 0，SUM 为 NULL。","SELECT count(*),sum(person_id) IS NULL FROM skill WHERE 0;","0|1")),
 T(296,"symmetric-set-difference","双向集合差输出单边键",["EXCEPT","对称差","集合对账"],
   "左集合有 A、B、C，右集合有 A、B、D，忽略重复次数后的对称差为 C、D。分别执行左减右、右减左再 UNION，避免复合查询结合顺序造成歧义。若还要对账重复数量，不能仅使用集合差。",
   "WITH l AS(SELECT k FROM bag WHERE side='L' EXCEPT SELECT k FROM bag WHERE side='R'),r AS(SELECT k FROM bag WHERE side='R' EXCEPT SELECT k FROM bag WHERE side='L') SELECT k FROM l UNION SELECT k FROM r ORDER BY k;","C\nD",
   ["集合运算默认去重，会隐藏重复次数差异。","多个复合运算应使用 CTE 明确分组。"],
   ("返回两边共有的不同键。","INTERSECT。","SELECT k FROM bag WHERE side='L' INTERSECT SELECT k FROM bag WHERE side='R' ORDER BY k;","A\nB"),
   ("返回两边所有不同键。","UNION 去重。","SELECT k FROM bag WHERE side='L' UNION SELECT k FROM bag WHERE side='R' ORDER BY k;","A\nB\nC\nD")),
 T(297,"multiset-difference-counts","模拟 EXCEPT ALL 保留重复数量差",["多重集合","计数相减","EXCEPT ALL"],
   "SQLite 没有 EXCEPT ALL，可先按键分别计数，再取 max(左次数-右次数,0)。左 A 有两次、右一次，剩 A 一次；C 仅左一次，也剩一次。输出键和剩余次数，避免为了重复行再次递归展开。",
   "WITH c AS(SELECT k,sum(side='L') l,sum(side='R') r FROM bag GROUP BY k) SELECT k,max(l-r,0) copies FROM c WHERE l>r ORDER BY k;","A|1\nC|1",
   ["普通 EXCEPT 会丢掉 A 的一次额外副本。","次数报告与重复行展开是两种输出契约。"],
   ("计算右多于左的键及差量。","交换计数相减方向。","WITH c AS(SELECT k,sum(side='L') l,sum(side='R') r FROM bag GROUP BY k) SELECT k,r-l FROM c WHERE r>l ORDER BY k;","B|1\nD|1"),
   ("输出全部键的左右出现次数。","条件聚合。","SELECT k,sum(side='L'),sum(side='R') FROM bag GROUP BY k ORDER BY k;","A|2|1\nB|1|2\nC|1|0\nD|0|1")),
 T(298,"multiset-intersection-counts","多重集合交集取出现次数较小者",["INTERSECT ALL","计数最小值","重复语义"],
   "多重集合交集每个键保留 MIN(左右次数)，A 与 B 各保留一次，C、D 因缺一边为零而排除。直接连接 bag 两份表会让 A 产生 2×1 行、B 产生 1×2 行，那不是正确的多重集合交集。",
   "WITH c AS(SELECT k,sum(side='L') l,sum(side='R') r FROM bag GROUP BY k) SELECT k,min(l,r) copies FROM c WHERE min(l,r)>0 ORDER BY k;","A|1\nB|1",
   ["内连接重复行相乘，不代表多重集合交集。","NULL 键比较需要明确集合等价规则。"],
   ("核对多重集合交集总副本数。","每键 MIN 后求和。","WITH c AS(SELECT k,sum(side='L') l,sum(side='R') r FROM bag GROUP BY k) SELECT sum(min(l,r)) FROM c;","2"),
   ("演示直接按键连接的行数。","重复次数相乘得到 4。","SELECT count(*) FROM bag l JOIN bag r ON l.k=r.k WHERE l.side='L' AND r.side='R';","4")),
 T(299,"jaccard-skill-similarity","Jaccard 相似度使用交集除并集",["Jaccard","推荐基线","集合比例"],
   "Ann 的集合为 SQL、Python，与 Bob 交一并二，相似度 0.5；与 Cara 交二并三为 0.6667；与 Dan 无交集为 0。相似度反映集合重叠，不代表技能水平或雇佣建议。并集为空时需要明确政策。",
   "SELECT p.name,round(1.0*(SELECT count(*) FROM(SELECT skill FROM skill WHERE person_id=1 INTERSECT SELECT skill FROM skill WHERE person_id=p.id))/(SELECT count(*) FROM(SELECT skill FROM skill WHERE person_id=1 UNION SELECT skill FROM skill WHERE person_id=p.id)),4) FROM person p WHERE id<>1 ORDER BY p.name;","Bob|0.5\nCara|0.6667\nDan|0.0",
   ["相似度不是方向性的覆盖率。","双方空集合时分母为零，需要单独定义。"],
   ("核对 Ann 与 Cara 的交集大小。","INTERSECT 后 COUNT。","SELECT count(*) FROM(SELECT skill FROM skill WHERE person_id=1 INTERSECT SELECT skill FROM skill WHERE person_id=3);","2"),
   ("核对 Ann 与 Dan 的并集大小。","UNION 后 COUNT。","SELECT count(*) FROM(SELECT skill FROM skill WHERE person_id=1 UNION SELECT skill FROM skill WHERE person_id=4);","4")),
 T(300,"pairwise-shared-skills","自连接统计人员对共享技能",["共现","自连接","对称去重"],
   "按相同 skill 自连接，并限制左 person_id 小于右 id，避免自配和对称重复。Ann/Cara 共享两项，Ann/Bob、Bob/Cara、Cara/Dan 各一项。skill 的复合主键保证同人技能不重复，否则共享数会膨胀。",
   "SELECT a.person_id,b.person_id,count(*) FROM skill a JOIN skill b ON a.skill=b.skill AND a.person_id<b.person_id GROUP BY a.person_id,b.person_id ORDER BY a.person_id,b.person_id;","1|2|1\n1|3|2\n2|3|1\n3|4|1",
   ["未限制 id 顺序会输出两份对称对。","重复技能来源应先归一到一人一技能。"],
   ("只返回共享至少两项技能的人员对。","HAVING COUNT>=2。","SELECT a.person_id,b.person_id FROM skill a JOIN skill b ON a.skill=b.skill AND a.person_id<b.person_id GROUP BY a.person_id,b.person_id HAVING count(*)>=2 ORDER BY a.person_id,b.person_id;","1|3"),
   ("返回 SQL 对应的人员组合数量。","SQL 有三人，共三对。","SELECT count(*) FROM skill a JOIN skill b ON a.skill=b.skill AND a.person_id<b.person_id WHERE a.skill='SQL';","3")),
 T(301,"conditional-skill-pivot","固定技能维度用条件聚合透视",["条件透视","MAX 标记","零覆盖"],
   "以 person 为主表左连技能，按 SQL、Python、Lua 输出是否具备的 0/1 列。MAX(条件) 不会因同人多技能而重复计数，COALESCE 可保留没有技能者的零。固定列适合少量稳定维度，动态技能应继续使用长表。",
   "SELECT p.name,coalesce(max(s.skill='SQL'),0),coalesce(max(s.skill='Python'),0),coalesce(max(s.skill='Lua'),0) FROM person p LEFT JOIN skill s ON s.person_id=p.id GROUP BY p.id ORDER BY p.name;","Ann|1|1|0\nBob|1|0|0\nCara|1|1|1\nDan|0|0|1",
   ["不能把技能字符串直接作为 GROUP BY 外的裸列。","新增技能不自动增加透视列。"],
   ("统计 SQL 与 Python 各自覆盖人数。","条件 SUM，主键防重复。","SELECT sum(skill='SQL'),sum(skill='Python') FROM skill;","3|2"),
   ("统计拥有 Lua 或 Rust 的不同人数。","COUNT DISTINCT 避免 Dan 被计两次。","SELECT count(DISTINCT person_id) FROM skill WHERE skill IN('Lua','Rust');","2")),
 T(302,"weighted-requirement-score","按要求权重计算覆盖分数",["加权覆盖","预聚合","评分口径"],
   "SQL 权重 2、Python 权重 3，先连接符合要求的技能再按人求和，Ann、Bob、Cara、Dan 为 5、2、5、0。额外技能不加分，分母为要求总权重 5；这种分数仅代表已定义规则的覆盖。",
   "WITH weight(skill,w) AS(VALUES('SQL',2),('Python',3)) SELECT p.name,coalesce(sum(w.w),0) FROM person p LEFT JOIN skill s ON s.person_id=p.id LEFT JOIN weight w USING(skill) GROUP BY p.id ORDER BY p.name;","Ann|5\nBob|2\nCara|5\nDan|0",
   ["规则权重应非负且总和大于零。","更多额外技能不应无意抬高要求覆盖率。"],
   ("返回 Bob 的加权覆盖百分比。","满足 SQL 的 2 分除总 5 分。","WITH w(skill,q) AS(VALUES('SQL',2),('Python',3)) SELECT round(100.0*sum(w.q)/(SELECT sum(q) FROM w),1) FROM skill s JOIN w USING(skill) WHERE s.person_id=2;","40.0"),
   ("计算每个要求缺少它的人数。","完整人群网格反查。","SELECT r.skill,count(*) FROM requirement r CROSS JOIN person p WHERE NOT EXISTS(SELECT 1 FROM skill s WHERE s.person_id=p.id AND s.skill=r.skill) GROUP BY r.skill ORDER BY r.skill;","Python|2\nSQL|1")),
 T(303,"rare-skill-ownership","唯一技能与常见技能的覆盖人数",["稀有属性","HAVING","所有者"],
   "先按 skill 统计不同持有人，只有 Rust 由 Dan 一人具备，SQL 三人、Python 与 Lua 各两人。连接回来源可返回唯一所有者，适合发现知识集中风险。稀有不等于重要，仍需业务优先级。",
   "WITH rare AS(SELECT skill FROM skill GROUP BY skill HAVING count(*)=1) SELECT s.skill,p.name FROM rare JOIN skill s USING(skill) JOIN person p ON p.id=s.person_id ORDER BY s.skill;","Rust|Dan",
   ["输入必须保证一人一技能，否则 COUNT(*) 失真。","拥有属性不等于掌握熟练度。"],
   ("按技能统计持有人数。","直接分组。","SELECT skill,count(*) FROM skill GROUP BY skill ORDER BY skill;","Lua|2\nPython|2\nRust|1\nSQL|3"),
   ("返回至少三人掌握的技能。","HAVING COUNT>=3。","SELECT skill FROM skill GROUP BY skill HAVING count(*)>=3 ORDER BY skill;","SQL")),
 T(304,"skill-cooccurrence","按人统计技能对的共现频次",["共现矩阵","技能对","组合分析"],
   "在同人技能内连接不同技能并以文本顺序约束 skill1<skill2，统计同时出现的人数。Python/SQL 共有两人，其余 Lua/Python、Lua/Rust、Lua/SQL 各一人。这里统计技能对而非人员对，两个方向的分组不要混淆。",
   "SELECT a.skill,b.skill,count(*) FROM skill a JOIN skill b ON a.person_id=b.person_id AND a.skill<b.skill GROUP BY a.skill,b.skill ORDER BY a.skill,b.skill;","Lua|Python|1\nLua|Rust|1\nLua|SQL|1\nPython|SQL|2",
   ["技能文本顺序只是去重手段，不代表先后关系。","共现不表示因果或学习路径。"],
   ("列出同时具备 Python 和 SQL 的用户。","同人两次 EXISTS。","SELECT name FROM person p WHERE EXISTS(SELECT 1 FROM skill WHERE person_id=p.id AND skill='Python') AND EXISTS(SELECT 1 FROM skill WHERE person_id=p.id AND skill='SQL') ORDER BY name;","Ann\nCara"),
   ("计算 Dan 可形成的不同技能对数。","两项技能形成一对。","SELECT count(*) FROM skill a JOIN skill b ON a.person_id=b.person_id AND a.skill<b.skill WHERE a.person_id=4;","1")),
 T(305,"bounded-team-cover","有限候选组合求最小要求覆盖",["集合覆盖","位掩码","有限枚举"],
   "仅针对 SQL、Python 两项要求编码为位 1、2，每人掩码由去重技能相加。枚举单人和两人候选，用按位或检查是否覆盖掩码 3，再找最小人数。最小解为 Ann 或 Cara 单人；这是小规模有界枚举，不是通用最优排班算法。",
   "WITH masks AS(SELECT p.id,p.name,coalesce(sum(CASE s.skill WHEN 'SQL' THEN 1 WHEN 'Python' THEN 2 ELSE 0 END),0) mask FROM person p LEFT JOIN skill s ON s.person_id=p.id GROUP BY p.id),candidate(label,n,mask) AS(SELECT name,1,mask FROM masks UNION ALL SELECT a.name||'+'||b.name,2,a.mask|b.mask FROM masks a JOIN masks b ON a.id<b.id),valid AS(SELECT * FROM candidate WHERE mask=3) SELECT label,n FROM valid WHERE n=(SELECT min(n) FROM valid) ORDER BY label;","Ann|1\nCara|1",
   ["该位编码只覆盖当前两项要求，不能静默扩展无限技能。","枚举组合在候选数量增大时增长很快。"],
   ("输出每个人的两项要求掩码。","SQL=1，Python=2，其余不计。","SELECT p.name,coalesce(sum(CASE s.skill WHEN 'SQL' THEN 1 WHEN 'Python' THEN 2 ELSE 0 END),0) FROM person p LEFT JOIN skill s ON s.person_id=p.id GROUP BY p.id ORDER BY p.name;","Ann|3\nBob|1\nCara|3\nDan|0"),
   ("核对四人可组成的无序二人组合数。","a.id<b.id。","SELECT count(*) FROM person a JOIN person b ON a.id<b.id;","6")),
 T(306,"team-quota-division","团队要求按每项人数配额判断",["带配额关系除法","团队覆盖","人数约束"],
   "要求团队至少两人有 SQL、两人有 Python。分别对团队和技能计人数，再用反存在检查任一不足要求，只有 Ann、Cara 组成的 T2 合格。把所有技能次数相加会误把一种技能过量抵消另一种短缺。",
   "WITH quota(skill,n) AS(VALUES('SQL',2),('Python',2)),teams AS(SELECT DISTINCT team FROM team_member),coverage AS(SELECT t.team,s.skill,count(*) n FROM team_member t JOIN skill s ON s.person_id=t.person_id GROUP BY t.team,s.skill) SELECT team FROM teams t WHERE NOT EXISTS(SELECT 1 FROM quota q WHERE coalesce((SELECT n FROM coverage c WHERE c.team=t.team AND c.skill=q.skill),0)<q.n) ORDER BY team;","T2",
   ["每项配额必须单独满足，不能只比较技能总数。","一人可覆盖多技能是否允许需业务定义。"],
   ("输出每个团队的 Python 覆盖人数。","左连接以保留没有 Python 的团队。","SELECT t.team,sum(EXISTS(SELECT 1 FROM skill s WHERE s.person_id=t.person_id AND s.skill='Python')) FROM team_member t GROUP BY t.team ORDER BY t.team;","T1|1\nT2|2\nT3|1"),
   ("输出每个团队 SQL 覆盖人数。","同样按成员只计一次。","SELECT t.team,sum(EXISTS(SELECT 1 FROM skill s WHERE s.person_id=t.person_id AND s.skill='SQL')) FROM team_member t GROUP BY t.team ORDER BY t.team;","T1|2\nT2|2\nT3|2")),
]
